sys_data_source.data_loader:
(function loadData(import_set_table, data_source, import_log, last_success_import_time) {

    try {
        var r = new sn_ws.RESTMessageV2('x_cesy_service_gr.Ceburu Provider', 'Get Ceburu Networks');

        var responseMessage = r.execute();
        var responseBody = JSON.parse(responseMessage.getBody());
        var httpStatus = responseMessage.getStatusCode();

        var networks = responseBody.result.networks;

        for (var j = 0; j < networks.length; j++) {

            var net = networks[j];

            var importRecord = {};
            importRecord.network_id = net.id;
            importRecord.name = net.name;
            importRecord.probe_name = net.probe_name;
            importRecord.probe_ip = net.probe_ip;
            importRecord.network_group_id = net.network_group_id;
            importRecord.customer_id = net.customer_id;

            import_set_table.insert(importRecord);
        }

    } catch (ex) {
        gs.error("Data Source (Ceburu Network) Error: " + ex.message);
    }

})(import_set_table, data_source, import_log, last_success_import_time);

